const input = $input.first().json;
const body = input.body || input;

// ── TEXT MODE (used by match_product) ──
if (body.text) {
  return [{
    json: {
      mode: 'text',
      prompt: String(body.text)
    }
  }];
}

// ── VISION MODE (used by analyze_media) ──
const base64 = String(body.base64 || '').trim();
const mime = String(body.mime || 'image/jpeg').trim();

if (!base64) {
  return [{ json: { error: 'missing_base64_or_text' } }];
}

const prompt = `أنت محلل صور لمطبعة العزازي. رجّع JSON فقط بدون أي كلام إضافي.

