={{ (() => {
  const mode = $json.mode;
  const parts = [{ text: $json.prompt }];
  if (mode === 'vision') {
    parts.push({ inline_data: { mime_type: $json.mime, data: $json.base64 } });
  }
  return JSON.stringify({
    contents: [{ parts }],
    generationConfig: { responseMimeType: 'application/json' }
  });
})() }}

