const { logTokens } = require('/files/token_tracker.js');
const resp = $input.first().json;
const mode = $('Build Prompt').first().json.mode;
const fail = (error, detail) => [{ json: { ok: false, error, mode, detail } }];
if (!['vision', 'text'].includes(mode)) return fail('invalid_mode', 'Expected vision or text');
try {
  const u = resp.usageMetadata;
  if (u) {
    const n = v => Math.max(0, Number(v) || 0);
    const prompt = n(u.promptTokenCount);
    const candidates = n(u.candidatesTokenCount);
    const thoughts = n(u.thoughtsTokenCount);
    // Native Gemini reports thoughts separately. Reconcile total to avoid adding twice.
    const completion = u.totalTokenCount != null
      ? Math.max(candidates, n(u.totalTokenCount) - prompt - n(u.toolUsePromptTokenCount))
      : candidates + thoughts;
    await logTokens({ provider: 'gemini', mode, prompt, completion, contactKey: null,
      meta: { model: 'gemini-3.1-flash-lite', source: 'gemini_analyze', thoughtsTokenCount: thoughts } });
  }
} catch (e) { console.log('[ParseResponse] token logging failed'); }
if (resp.error) return fail('gemini_provider_error', 'Provider returned an error');
const candidate = resp.candidates?.[0];
if (!candidate || (candidate.finishReason && candidate.finishReason !== 'STOP'))
  return fail('gemini_incomplete_response', candidate?.finishReason || 'No candidate');
const text = (candidate.content?.parts || []).filter(p => !p.thought && typeof p.text === 'string').map(p => p.text).join('').trim();
if (!text) return fail('gemini_empty_response', 'No response text');
let data;
try { data = JSON.parse(text); } catch (e) { return fail('gemini_parse_failed', 'Response is not valid JSON'); }
if (!data || typeof data !== 'object' || Array.isArray(data)) return fail('gemini_schema_invalid', 'Expected JSON object');
const str = v => typeof v === 'string';
const conf = v => typeof v === 'number' && Number.isFinite(v) && v >= 0 && v <= 1;
if (mode === 'text') {
  if (typeof data.matched !== 'boolean' || !(data.matched_product_id === null || str(data.matched_product_id)) ||
      (data.matched && !data.matched_product_id) || !conf(data.confidence) || !str(data.reason) ||
      !Array.isArray(data.alternatives) || !data.alternatives.every(a => a && str(a.id) && conf(a.confidence)))
    return fail('gemini_schema_invalid', 'Invalid product-matching fields');
  return [{ json: data }];
}
const types = ['transfer_receipt','design','invoice','screenshot','photo','document','other'];
const services = ['كروت شخصية','كروت PVC','استيكر','استيكر بلاستيك','بانر اوت دور','فينيل','سي ثرو','كانفس','رول اب استاند','فوم','طباعة ورق','فلايرات','ورق شركة','فولدر','أظرف','تيشرت','مج','بينز','سلوفان','تجليد','تدبيس','لوحات هندسية','اسكانر','غير محدد',''];
if (!types.includes(data.type) || typeof data.is_transfer_receipt !== 'boolean' ||
    !str(data.transfer_provider) || !str(data.transfer_amount) || !str(data.description) || !data.description.trim() ||
    !services.includes(data.likely_print_service) || !Array.isArray(data.visual_keywords) ||
    !data.visual_keywords.every(str) || data.visual_keywords.length > 8 ||
    (data.is_transfer_receipt && data.type !== 'transfer_receipt'))
  return fail('gemini_schema_invalid', 'Invalid image-analysis fields');

if (data._audit !== undefined) {
  const a = data._audit;
  const nullable = v => v === null || typeof v === 'string';
  if (!a || typeof a !== 'object' || Array.isArray(a) || a.schema_version !== '1' ||
      typeof a.readable !== 'boolean' || typeof a.visible_summary_ar !== 'string' ||
      !['not_receipt','success_shown','pending_shown','failed_shown','unclear'].includes(a.receipt_status) ||
      !['amount','currency','recipient_visible','transaction_date_visible','invoice_total_visible'].every(k=>nullable(a[k])) ||
      !Array.isArray(a.limitations) || !a.limitations.every(v=>typeof v==='string')) {
    delete data._audit;
  } else {
    data._audit = Object.fromEntries(['schema_version','readable','visible_summary_ar','receipt_status','amount','currency','recipient_visible','transaction_date_visible','invoice_total_visible','limitations'].map(k=>[k,a[k]]));
  }
}
return [{ json: data }];
